schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/single-page-case-study-generation.json",
  "title": "Single Page Case Study Generation report",
  "type": "object",
  "required": ["publication_version", "dates", "title", "slots", "word_count", "media_count", "anonymisation", "inputs_used", "cta", "outcome_review"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "ref": {"type": "string", "minLength": 5}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "publication_version": {"type": "string", "enum": ["named", "anonymised", "internal_log_only"]},
    "dates": {
      "type": "object",
      "required": ["delivery_date", "draft_date", "publish_or_park_date", "status"],
      "additionalProperties": false,
      "properties": {
        "delivery_date": {"$ref": "#/definitions/date"},
        "draft_date": {"$ref": "#/definitions/date"},
        "publish_or_park_date": {"$ref": "#/definitions/date"},
        "status": {"type": "string", "enum": ["published", "parked"]},
        "park_reason": {"type": "string", "minLength": 10},
        "revisit_date": {"$ref": "#/definitions/date"}
      },
      "if": {"properties": {"status": {"const": "parked"}}},
      "then": {"required": ["park_reason", "revisit_date"]}
    },
    "title": {
      "type": "string",
      "minLength": 20,
      "maxLength": 120,
      "pattern": "[0-9]",
      "not": {"pattern": "^(Backend|Frontend|Fullstack|Full-stack|Consulting|Development|Engineering|Design|Our |We |I |My )"}
    },
    "slots": {
      "type": "object",
      "required": ["problem", "approach", "outcome", "numbers", "pull_quote", "nda_indicator"],
      "additionalProperties": false,
      "properties": {
        "problem": {
          "type": "object",
          "required": ["text", "sentences"],
          "additionalProperties": false,
          "properties": {"text": {"type": "string", "minLength": 30}, "sentences": {"type": "integer", "minimum": 1, "maximum": 2}}
        },
        "approach": {
          "type": "object",
          "required": ["text", "sentences", "stack_or_method"],
          "additionalProperties": false,
          "properties": {"text": {"type": "string", "minLength": 60}, "sentences": {"type": "integer", "minimum": 2, "maximum": 3}, "stack_or_method": {"type": "string", "minLength": 3}}
        },
        "outcome": {
          "type": "object",
          "required": ["text", "sentences"],
          "additionalProperties": false,
          "properties": {"text": {"type": "string", "minLength": 20, "pattern": "[0-9]", "not": {"pattern": "(?i)significant|dramatic|huge|massive"}}, "sentences": {"const": 1}}
        },
        "numbers": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["metric", "baseline", "final", "unit", "delta_pct", "window", "source_system", "evidence_ref"],
            "additionalProperties": false,
            "properties": {
              "metric": {"type": "string", "minLength": 3},
              "baseline": {"type": "number"},
              "final": {"type": "number"},
              "unit": {"type": "string", "minLength": 1},
              "delta_pct": {"type": "number"},
              "window": {"type": "string", "minLength": 8},
              "source_system": {"type": "string", "enum": ["stripe_export", "server_logs", "ga4_report", "calendar", "pnl", "ticket_tracker", "other_named_system"]},
              "evidence_ref": {"$ref": "#/definitions/ref"}
            }
          }
        },
        "pull_quote": {
          "type": "object",
          "required": ["text", "contact_role", "permission_captured_in", "permission_ref"],
          "additionalProperties": false,
          "properties": {
            "text": {"type": "string", "minLength": 20, "not": {"pattern": "(?i)the client (was|were|is) (very )?(happy|pleased|satisfied)"}},
            "contact_name": {"type": "string", "minLength": 3},
            "contact_role": {"type": "string", "minLength": 3},
            "company": {"type": "string", "minLength": 2},
            "company_descriptor": {"type": "string", "minLength": 10},
            "permission_captured_in": {"type": "string", "enum": ["email", "message"]},
            "permission_ref": {"$ref": "#/definitions/ref"}
          }
        },
        "nda_indicator": {"type": "string", "enum": ["named", "anonymised", "full_version_on_request"]}
      }
    },
    "word_count": {"type": "integer", "minimum": 1, "maximum": 500},
    "media_count": {"type": "integer", "minimum": 0, "maximum": 1},
    "anonymisation": {
      "anyOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["industry", "size_band", "context", "quoted_role", "client_consent_ref", "identifiers_removed"],
          "additionalProperties": false,
          "properties": {
            "industry": {"type": "string", "minLength": 3},
            "size_band": {"type": "string", "minLength": 3},
            "context": {"type": "string", "minLength": 3},
            "quoted_role": {"type": "string", "minLength": 3},
            "client_consent_ref": {"$ref": "#/definitions/ref"},
            "identifiers_removed": {"const": true}
          }
        }
      ]
    },
    "inputs_used": {
      "type": "array",
      "minItems": 2,
      "items": {
        "type": "object",
        "required": ["name", "path"],
        "additionalProperties": false,
        "properties": {"name": {"$ref": "#/definitions/ref"}, "path": {"type": "string", "minLength": 5}}
      }
    },
    "cta": {
      "type": "object",
      "required": ["count", "target", "url"],
      "additionalProperties": false,
      "properties": {
        "count": {"const": 1},
        "target": {"const": "discovery_call"},
        "url": {"type": "string", "pattern": "^https?://.*(utm_|[?&]ref=|/r/)"}
      }
    },
    "outcome_review": {
      "type": "object",
      "required": ["due_date", "findings"],
      "additionalProperties": false,
      "properties": {
        "due_date": {"$ref": "#/definitions/date"},
        "findings": {
          "anyOf": [
            {"type": "null"},
            {
              "type": "object",
              "required": ["held_on", "discovery_calls_attributed", "included_in_closed_proposal"],
              "additionalProperties": false,
              "properties": {
                "held_on": {"$ref": "#/definitions/date"},
                "discovery_calls_attributed": {"type": "integer", "minimum": 0},
                "included_in_closed_proposal": {"type": "boolean"}
              }
            }
          ]
        }
      }
    }
  },
  "allOf": [
    {"if": {"properties": {"publication_version": {"const": "named"}}}, "then": {"properties": {"anonymisation": {"type": "null"}, "slots": {"properties": {"pull_quote": {"required": ["contact_name", "company"]}, "nda_indicator": {"enum": ["named", "full_version_on_request"]}}}}}},
    {"if": {"properties": {"publication_version": {"const": "anonymised"}}}, "then": {"properties": {"anonymisation": {"type": "object"}, "slots": {"properties": {"pull_quote": {"required": ["company_descriptor"], "not": {"required": ["contact_name"]}}, "nda_indicator": {"const": "anonymised"}}}}}}
  ]
}

example.code:
{
  "publication_version": "named",
  "dates": {"delivery_date": "2026-08-28", "draft_date": "2026-09-02", "publish_or_park_date": "2026-09-09", "status": "published"},
  "title": "How Kestrel Pay cut checkout latency 62 percent in 3 weeks",
  "slots": {
    "problem": {"text": "Kestrel Pay's hosted checkout took 1.5 seconds at the 95th percentile and merchants were escalating abandoned carts every week. The team had no capacity to profile it between feature releases.", "sentences": 2},
    "approach": {"text": "Over three weeks I profiled the checkout path with OpenTelemetry traces and found two serial calls to the risk service. I collapsed them into one batched gRPC call and moved the currency lookup to a Redis cache with a 10-minute TTL. The change shipped behind a feature flag and was rolled out to 100 percent over four days.", "sentences": 3, "stack_or_method": "OpenTelemetry, gRPC batching, Redis cache, feature-flagged rollout"},
    "outcome": {"text": "p95 checkout latency fell from 1,480 ms to 560 ms, a 62 percent reduction, within three weeks of the first trace.", "sentences": 1},
    "numbers": [
      {"metric": "p95 checkout latency", "baseline": 1480, "final": 560, "unit": "ms", "delta_pct": -62.2, "window": "30 days before vs 30 days after rollout", "source_system": "server_logs", "evidence_ref": "grafana-p95-export-2026-08.csv"},
      {"metric": "checkout abandonment", "baseline": 18.4, "final": 14.1, "unit": "percent", "delta_pct": -23.4, "window": "30 days before vs 30 days after rollout", "source_system": "ga4_report", "evidence_ref": "ga4-checkout-funnel-2026-08.csv"}
    ],
    "pull_quote": {"text": "Checkout stopped being the thing we apologised for in every merchant call.", "contact_name": "Maria Voss", "contact_role": "VP Engineering", "company": "Kestrel Pay", "permission_captured_in": "email", "permission_ref": "permission-voss-2026-09-01.eml"},
    "nda_indicator": "named"
  },
  "word_count": 310,
  "media_count": 1,
  "anonymisation": null,
  "inputs_used": [
    {"name": "grafana-p95-export-2026-08.csv", "path": "evidence/kestrel-pay/grafana-p95-export-2026-08.csv"},
    {"name": "ga4-checkout-funnel-2026-08.csv", "path": "evidence/kestrel-pay/ga4-checkout-funnel-2026-08.csv"},
    {"name": "permission-voss-2026-09-01.eml", "path": "evidence/kestrel-pay/permission-voss-2026-09-01.eml"}
  ],
  "cta": {"count": 1, "target": "discovery_call", "url": "https://example.com/book?utm_source=case-study&utm_campaign=kestrel-latency"},
  "outcome_review": {"due_date": "2026-12-08", "findings": null}
}

