    "approach": {"text": "I fixed it.", "sentences": 1, "stack_or_method": ""},
    "outcome": {"text": "A significant improvement in checkout performance.", "sentences": 1},
    "numbers": [
      {"metric": "latency", "baseline": 0, "final": 0, "unit": "", "delta_pct": -60, "window": "later", "source_system": "the client told me", "evidence_ref": "n/a"}
    ],
    "pull_quote": {"text": "The client was very happy with the result.", "contact_role": "", "permission_captured_in": "verbal", "permission_ref": "none"},
    "nda_indicator": "named"
  },
  "word_count": 900,
  "media_count": 3,
  "anonymisation": null,
  "inputs_used": [],
  "cta": {"count": 3, "target": "contact_page", "url": "https://example.com/contact"},
